// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address to, uint256 amount) public {
        vm.assume(to != address(0));
        vm.assume(amount > 0 && amount <= type(uint256).max / 1e18);
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory vs = new uint256[](1);
        vs[0] = amount;
        bool ok = true;
        bool ret = true;
        try c.transfer(tos, vs) returns (bool r) { ret = r; } catch { ok = false; }
        // Rule: whenever the call completes, it reports success (true).
        assertTrue(ok ? ret : true, "completed transfer must return true");
    }
}
